13	pub(crate) async fn execute(args: UpgradeArgs) -> Result<CliExitCode, crate::CliError> {
14	    let client = ReqwestReleaseClient::new().map_err(|error| message(error.to_string()))?;
15	    run_upgrade(&args, &client).await
16	}
17	
18	async fn run_upgrade(
19	    args: &UpgradeArgs,
20	    client: &dyn ReleaseClient,
21	) -> Result<CliExitCode, crate::CliError> {
22	    let target = current_exe_path()?;
23	    let reporter = StdoutUpgradeReporter;
24	    run_upgrade_with(args, client, &target, &reporter).await
25	}
26	
27	async fn run_upgrade_with(
28	    args: &UpgradeArgs,
29	    client: &dyn ReleaseClient,
30	    target: &Path,
31	    reporter: &dyn UpgradeReporter,
32	) -> Result<CliExitCode, crate::CliError> {
33	    let release = client
34	        .latest_release()
35	        .await
36	        .map_err(|error| message(error.to_string()))?;
37	    let current = current_version()?;
38	    let latest = release_version(&release)?;
39	    let upgrade_available = latest > current;
40	
41	    if args.check {
42	        if upgrade_available {
43	            reporter.line(&format!(
44	                "derrick {latest} is available (current {current})"
45	            ));
46	            return Ok(CliExitCode::UpgradeAvailable);
47	        }
48	        reporter.line(&format!(
49	            "derrick is already up to date (current {current}, latest {latest})"
50	        ));
51	        return Ok(CliExitCode::Success);
52	    }
53	
54	    if !upgrade_available && !args.force {
55	        reporter.line(&format!(
56	            "derrick is already up to date (current {current}, latest {latest})"
57	        ));
58	        return Ok(CliExitCode::Success);
59	    }
60	
61	    if !upgrade_available {
62	        reporter.line(&format!("forcing upgrade to {latest} (current {current})"));
63	    } else {
64	        reporter.line(&format!("upgrading derrick from {current} to {latest}"));
65	    }
66	
67	    let asset = select_asset(&release)?;
68	    reporter.line(&format!("downloading {}", asset.name));
69	    let written = download_and_replace(target, client, asset).await?;
70	    reporter.line(&format!("downloaded {written} bytes"));
71	    reporter.line(&format!("upgraded derrick to {latest}"));
72	    Ok(CliExitCode::Success)
73	}
74	
75	fn current_exe_path() -> Result<PathBuf, crate::CliError> {
76	    let path = std::env::current_exe().map_err(|source| crate::CliError::Io {
77	        path: PathBuf::from("derrick"),
78	        source,
79	    })?;
80	    fs::canonicalize(&path).map_err(|source| crate::CliError::Io { path, source })
81	}
82	
83	fn current_version() -> Result<Version, crate::CliError> {
84	    parse_version(env!("CARGO_PKG_VERSION"))
85	}
86	
87	fn release_version(release: &GithubRelease) -> Result<Version, crate::CliError> {
88	    parse_version(&release.tag_name)
89	}
