91	fn parse_version(raw: &str) -> Result<Version, crate::CliError> {
92	    let trimmed = raw.trim().trim_start_matches('v');
93	    Version::parse(trimmed)
94	        .map_err(|error| message(format!("invalid release version {raw:?}: {error}")))
95	}
96	
97	fn select_asset(release: &GithubRelease) -> Result<&ReleaseAsset, crate::CliError> {
98	    let expected = expected_asset_name()?;
99	    release
100	        .assets
101	        .iter()
102	        .find(|asset| asset.name == expected)
103	        .ok_or_else(|| {
104	            message(format!(
105	                "release {} does not include asset {expected}",
106	                release.tag_name
107	            ))
108	        })
109	}
110	
111	fn expected_asset_name() -> Result<&'static str, crate::CliError> {
112	    match (std::env::consts::OS, std::env::consts::ARCH) {
113	        ("linux", "x86_64") => Ok("derrick-linux-x86_64"),
114	        ("macos", "aarch64") => Ok("derrick-macos-arm64"),
115	        ("macos", "x86_64") => Ok("derrick-macos-x86_64"),
116	        (os, arch) => Err(message(format!(
117	            "unsupported upgrade platform {os}-{arch}; reinstall with scripts/install.sh"
118	        ))),
119	    }
120	}
121	
122	async fn download_and_replace(
123	    target: &Path,
124	    client: &dyn ReleaseClient,
125	    asset: &ReleaseAsset,
126	) -> Result<u64, crate::CliError> {
127	    let parent = target
128	        .parent()
129	        .filter(|p| !p.as_os_str().is_empty())
130	        .ok_or_else(|| message(format!("cannot determine parent for {}", target.display())))?;
131	
132	    let mut tmp = NamedTempFile::new_in(parent).map_err(|source| crate::CliError::Io {
133	        path: parent.to_path_buf(),
134	        source,
135	    })?;
136	
137	    let written = {
138	        use std::io::Write as _;
139	        let file = tmp.as_file_mut();
140	        let total = client
141	            .download_asset(asset, file)
142	            .await
143	            .map_err(|error| message(error.to_string()))?;
144	        file.flush().map_err(|source| crate::CliError::Io {
145	            path: tmp.path().to_path_buf(),
146	            source,
147	        })?;
148	        total
149	    };
150	
151	    apply_executable_permissions(tmp.path(), target)?;
152	    let temp_path = tmp.into_temp_path();
153	    let kept = temp_path.keep().map_err(|error| crate::CliError::Io {
154	        path: error.path.to_path_buf(),
155	        source: error.error,
156	    })?;
157	    if let Err(error) = rename_with_help(&kept, target) {
158	        let _ = fs::remove_file(&kept);
159	        return Err(error);
160	    }
161	    Ok(written)
162	}
