164	#[cfg(unix)]
165	fn apply_executable_permissions(temp: &Path, target: &Path) -> Result<(), crate::CliError> {
166	    use std::os::unix::fs::PermissionsExt as _;
167	
168	    // Inherit the target's existing mode (preserving any deliberate
169	    // restrictions like 0o700) and ensure the execute bits are set so the
170	    // replacement is invocable.
171	    let mode = match fs::metadata(target) {
172	        Ok(metadata) => metadata.permissions().mode(),
173	        Err(error) if error.kind() == io::ErrorKind::NotFound => 0o755,
174	        Err(source) => {
175	            return Err(crate::CliError::Io {
176	                path: target.to_path_buf(),
177	                source,
178	            });
179	        }
180	    };
181	    let mut permissions = fs::metadata(temp)
182	        .map_err(|source| crate::CliError::Io {
183	            path: temp.to_path_buf(),
184	            source,
185	        })?
186	        .permissions();
187	    permissions.set_mode((mode & 0o777) | 0o111);
188	    fs::set_permissions(temp, permissions).map_err(|source| crate::CliError::Io {
189	        path: temp.to_path_buf(),
190	        source,
191	    })
192	}
193	
194	#[cfg(not(unix))]
195	fn apply_executable_permissions(_temp: &Path, _target: &Path) -> Result<(), crate::CliError> {
196	    Ok(())
197	}
198	
199	fn rename_with_help(from: &Path, to: &Path) -> Result<(), crate::CliError> {
200	    fs::rename(from, to).map_err(|source| rename_error(to, source))
201	}
202	
203	fn rename_error(target: &Path, source: io::Error) -> crate::CliError {
204	    if source.kind() == io::ErrorKind::PermissionDenied {
205	        let location = target.parent().map_or_else(
206	            || target.display().to_string(),
207	            |parent| parent.display().to_string(),
208	        );
209	        return message(format!(
210	            "permission denied replacing {}; rerun with permission to write {location} or reinstall with the install script",
211	            target.display()
212	        ));
213	    }
214	    crate::CliError::Io {
215	        path: target.to_path_buf(),
216	        source,
217	    }
218	}
