 }

 impl FakeReleaseClient {
 fn new(tag_name: &str, bytes: &[u8]) -> TestResult<Self> {
 Ok(Self {
 release: GithubRelease {
 tag_name: tag_name.to_owned(),
 assets: vec![ReleaseAsset {
